/* Kelime Defteri: ek B1 okuma parçaları (tools/reading/b1.py üretir). */
(function(){var A=[{"id": "hotel7", "t": "Booking a Hotel Online", "lv": "B1", "g": [["booking", "rezervasyon"], ["review", "yorum, değerlendirme"], ["included", "dahil"], ["cancel", "iptal etmek"], ["view", "manzara"], ["refund", "para iadesi"]], "p": ["Last spring, my cousin Ece and I decided to spend a weekend in Izmir. We had only a week to plan, so we looked for a hotel on the internet. There were hundreds of choices, and at first it was difficult to decide.", "Ece wanted the cheapest room, but I preferred to read the reviews first. One hotel cost very little, but many guests wrote that the rooms were noisy and the breakfast was not included. Another one was slightly more expensive, yet people said the staff were friendly and there was a lovely view of the sea. We chose the second one.", "Before we paid, I checked the cancellation rules. The booking could be cancelled free of charge until two days before our arrival, and after that we would get only half of our money back. That seemed fair, so we confirmed the reservation and received an email within minutes.", "The weekend was perfect. Our room was on the fourth floor, and every morning we had tea on the balcony and watched the boats. At the end, I wrote a short review myself. I think reviews are useful, because the next guests can learn from our experience, just as we learnt from other people's."], "q": [{"q": "Why did the writer choose the second hotel?", "o": ["It was the cheapest one online.", "Guests praised the staff and the view.", "Ece had stayed there before.", "Breakfast was included in the price."], "a": 1, "e": "Yorumlarda personel ve manzara övülüyordu."}, {"q": "What happens if they cancel one day before arrival?", "o": ["They pay nothing at all.", "They lose all their money.", "They have to book another room.", "They get back half of the money."], "a": 3, "e": "İki günden sonra yalnızca yarı iade var."}, {"q": "What did the writer do after the weekend?", "o": ["She sent an email to Ece.", "She wrote her own opinion of the hotel.", "She asked for a refund.", "She booked the same room again."], "a": 1, "e": "\"I wrote a short review myself.\""}, {"q": "What is the writer's opinion about reviews?", "o": ["They are usually not honest.", "They are too long to read.", "They only matter for cheap hotels.", "They help future guests decide."], "a": 3, "e": "Sonraki misafirler deneyimlerden öğrenir."}]}, {"id": "doctor7", "t": "At the Doctor's", "lv": "B1", "g": [["appointment", "randevu"], ["symptom", "belirti"], ["prescription", "reçete"], ["fever", "ateş"], ["rest", "dinlenmek"], ["recover", "iyileşmek"]], "p": ["On Monday morning, Burak woke up with a sore throat and a headache. He did not have a fever, so he thought it was only a cold. By the evening, however, he felt much worse, and his mother made an appointment with Dr Aksoy for the next day.", "In the waiting room, there were five other patients. Burak had to wait for twenty minutes, which he found boring, so he read an old magazine about gardens. At last, the nurse called his name.", "Dr Aksoy asked him about his symptoms and looked at his throat. \"You have an infection,\" she said. \"I'll give you a prescription for some medicine. Take it three times a day after meals, and drink plenty of water.\" She also told him to stay at home for three days and not to go to football training until he felt completely well.", "Burak took the prescription to the pharmacy near his house. The pharmacist explained that the medicine could make him a little sleepy, so he should not do any sport. Four days later he had recovered, and he was happy to be back at school. \"Next time,\" he said, \"I'll go to the doctor sooner.\""], "q": [{"q": "Why did Burak's mother call the doctor?", "o": ["He felt worse during the day.", "He had a high fever on Monday.", "He had missed football training.", "He wanted to leave school early."], "a": 0, "e": "Akşama doğru çok daha kötüydü."}, {"q": "What did Burak do in the waiting room?", "o": ["He talked to the nurse.", "He played on his phone.", "He read a magazine.", "He fell asleep."], "a": 2, "e": "Bahçe dergisini okudu."}, {"q": "What did the doctor tell Burak to do?", "o": ["Take medicine and avoid training for a while.", "Go to hospital for more tests.", "Eat nothing for three days.", "Go back to school the next day."], "a": 0, "e": "İlaç, bol su ve üç gün evde dinlenme."}, {"q": "What does Burak say at the end?", "o": ["He will never go to football again.", "He doesn't trust the pharmacist.", "He will see a doctor earlier in future.", "He thinks doctors are too slow."], "a": 2, "e": "\"Next time I'll go to the doctor sooner.\""}]}, {"id": "driving7", "t": "Learning to Drive", "lv": "B1", "g": [["driving test", "sürücü sınavı"], ["lesson", "ders"], ["instructor", "eğitmen"], ["roundabout", "döner kavşak"], ["nervous", "gergin"], ["licence", "ehliyet"]], "p": ["When Selin turned eighteen, she decided to learn to drive. Her parents were pleased, because they were tired of taking her everywhere. She signed up at a driving school near her house and had her first lesson the following Monday.", "Her instructor, Mr Polat, was a calm man who never raised his voice. In the first lesson, they practised in an empty car park. Selin found it hard to start the car smoothly, and the engine stopped three times. She laughed about it, but inside she was nervous.", "After ten lessons, she felt more confident and began driving on real roads. The roundabouts were the most difficult part, because she never knew when to enter. \"Look to the right and wait for a gap,\" Mr Polat said every time. Slowly, it became easier.", "In March, she took her theory test and passed it at the first attempt. The driving test was harder: she made a small mistake and had to try again a month later. This time she was calm, and the examiner smiled at the end. \"You have passed,\" he said. Selin could not stop smiling all the way home."], "q": [{"q": "How did Selin feel in her first lesson?", "o": ["She was bored with the car park.", "She was angry with Mr Polat.", "She was completely relaxed.", "She was anxious but tried to laugh."], "a": 3, "e": "\"She laughed about it, but inside she was nervous.\""}, {"q": "What was most difficult for Selin on the road?", "o": ["starting the engine", "deciding when to enter a roundabout", "parking in small spaces", "driving at night"], "a": 1, "e": "Döner kavşakta ne zaman girileceğini bilmiyordu."}, {"q": "What happened in the first driving test?", "o": ["She passed it easily.", "She cancelled it.", "She forgot her documents.", "She made a mistake and failed."], "a": 3, "e": "Küçük bir hata yaptı ve bir ay sonra yeniden girdi."}, {"q": "How did Selin feel at the end?", "o": ["disappointed", "delighted", "worried", "embarrassed"], "a": 1, "e": "\"Selin could not stop smiling.\""}]}, {"id": "festival7", "t": "The Spring Festival", "lv": "B1", "g": [["festival", "festival, şenlik"], ["parade", "geçit töreni"], ["costume", "kostüm"], ["tradition", "gelenek"], ["stall", "tezgâh"], ["crowd", "kalabalık"]], "p": ["Every April, our town holds a spring festival that lasts three days. People come from nearby villages, and the main street is closed to traffic. For us children, it is the best time of the year.", "The festival begins on Friday with a parade. Students from every school walk down the street in colourful costumes, and a band plays traditional music. My class dressed as flowers last year, and my little brother, who was a bee, refused to take off his wings for a week!", "On Saturday, there are stalls with local food, handmade toys and flowers. My grandmother always sells her homemade jam, and she usually runs out of it by noon. In the evening, there is a concert in the square, and the whole crowd sings together, even if they don't know the words.", "The festival ends on Sunday with a picnic by the river. Families bring blankets and share their food with their neighbours. I like this tradition because it makes the town feel like one big family. If you are ever in the area in April, you should come and see it."], "q": [{"q": "What happens on the first day of the festival?", "o": ["People sell jam in the square.", "Families have a picnic.", "Students walk in a parade.", "A concert is held by the river."], "a": 2, "e": "Cuma: geçit töreni."}, {"q": "What does the writer say about his little brother?", "o": ["He loved his costume very much.", "He was frightened of the crowd.", "He did not want to be in the parade.", "He sold flowers at a stall."], "a": 0, "e": "Kanatlarını bir hafta çıkarmak istemedi."}, {"q": "Why does the writer like the picnic?", "o": ["The food is better than at the stalls.", "It is the shortest part of the festival.", "It makes people feel close to each other.", "Nobody has to bring anything."], "a": 2, "e": "Kasabayı büyük bir aile gibi hissettiriyor."}, {"q": "Who is the text written for?", "o": ["people who might visit the town", "students in the writer's school", "the town council", "shop owners"], "a": 0, "e": "Son cümle: \"if you are ever in the area... come and see it\"."}]}, {"id": "jobs7", "t": "A Part-Time Job", "lv": "B1", "g": [["part-time", "yarı zamanlı"], ["shift", "vardiya"], ["experience", "deneyim"], ["wage", "ücret"], ["customer", "müşteri"], ["balance", "denge kurmak"]], "p": ["Many students want to earn some money while they study, and I am no exception. Last autumn, I started working in a bookshop on Saturdays and two evenings a week. The wage is not high, but I enjoy the job more than I expected.", "My day begins at nine, when I open the shop with my manager, Mrs Yılmaz. First, we put the new books on the shelves. Then I help customers find what they need. Some of them are very polite, but others get impatient when I cannot find a title immediately.", "The job has taught me a lot. I have learnt to stay calm, to listen carefully and to organise my time. It is not always easy to balance work and study, though. Before exams, I asked Mrs Yılmaz for fewer shifts, and she kindly agreed.", "My advice to other students is to look for a job that fits their timetable. A part-time job gives you experience, which is useful when you apply for a full-time job later. But never forget that your studies come first."], "q": [{"q": "What does the writer say about the pay?", "o": ["It is much higher than expected.", "It is low, but the job is enjoyable.", "It is the reason she took the job.", "It depends on the number of customers."], "a": 1, "e": "\"The wage is not high, but I enjoy the job more.\""}, {"q": "What is difficult about the job sometimes?", "o": ["Opening the shop alone", "Carrying heavy boxes", "Working on Sundays", "Customers who are impatient"], "a": 3, "e": "Bazı müşteriler kitabı hemen bulamayınca sabırsızlanıyor."}, {"q": "What did the writer do before her exams?", "o": ["She left the job for a month.", "She asked to work fewer shifts.", "She studied in the shop.", "She changed her timetable at school."], "a": 1, "e": "Daha az vardiya istedi."}, {"q": "What is her advice to students?", "o": ["Never work during the school year.", "Look for the highest salary.", "Work as many hours as possible.", "Choose a job that suits their lessons."], "a": 3, "e": "Programa uyan bir iş bulun; dersler önce gelir."}]}, {"id": "flight7", "t": "My First Flight", "lv": "B1", "g": [["boarding pass", "biniş kartı"], ["luggage", "bagaj"], ["security", "güvenlik kontrolü"], ["gate", "kapı (havalimanı)"], ["take off", "havalanmak"], ["landing", "iniş"]], "p": ["I had never travelled by plane before, so I was both excited and afraid when my family went to Antalya last summer. We arrived at the airport three hours early, because my father hates being late.", "First, we left our luggage at the check-in desk and received our boarding passes. Then we went through security, where I had to take off my belt and put my bag on a belt. It was easier than I imagined, but I was glad my mother was there to tell me what to do.", "At the gate, we waited for almost an hour. When they finally called our flight, I felt my heart beating faster. Inside the plane, I sat next to the window, and my sister sat beside me. During take-off, I held the armrest tightly. After a few minutes, however, the plane was in the clouds, and I started to relax.", "The view was incredible: the sea looked like a blue carpet, and the cars were tiny. The landing was smooth, and everyone clapped. \"Was it that terrible?\" my father asked. I answered that I wanted to fly again as soon as possible."], "q": [{"q": "Why did the family arrive early at the airport?", "o": ["The writer's father doesn't like to be late.", "The flight had been cancelled.", "They wanted to go shopping.", "Their luggage was very heavy."], "a": 0, "e": "\"my father hates being late\""}, {"q": "How did the writer feel about security?", "o": ["It took a very long time.", "It was frightening.", "It was simpler than he had thought.", "It was boring."], "a": 2, "e": "\"It was easier than I imagined.\""}, {"q": "What did the writer do during take-off?", "o": ["He held the armrest tightly.", "He closed his eyes and slept.", "He talked to his sister.", "He looked out of the window."], "a": 0, "e": "Kol dayanağını sıkıca tuttu."}, {"q": "How did he feel at the end of the flight?", "o": ["He was relieved it was over.", "He felt sick.", "He wanted to fly again soon.", "He was sorry he had come."], "a": 2, "e": "En kısa sürede yeniden uçmak istedi."}]}, {"id": "fashion7", "t": "The True Cost of Fast Fashion", "lv": "B2", "g": [["fast fashion", "hızlı moda"], ["landfill", "çöp sahası"], ["textile", "tekstil"], ["garment", "giysi"], ["sustainable", "sürdürülebilir"], ["thrift", "ikinci el / tasarruf"]], "p": ["A T-shirt for the price of a sandwich sounds like a bargain, but few shoppers stop to ask how it can possibly be so cheap. Fast fashion, the business model that produces trendy clothes at very low prices, depends on speed and volume: some brands now release thousands of new designs every week.", "The consequences are considerable. Producing a single cotton T-shirt can require around two and a half thousand litres of water, and synthetic fabrics release tiny plastic fibres every time they are washed. Meanwhile, the average garment is worn only a handful of times before it is thrown away, and much of it ends up in landfill.", "There are also human costs. In order to keep prices down, many companies buy from factories where workers earn very little and conditions can be unsafe. Because supply chains are so long and complicated, even well-meaning shoppers find it difficult to know who made their clothes.", "Encouragingly, attitudes are beginning to change. Second-hand shops and online resale platforms are growing rapidly, and some young people proudly describe themselves as \"thrifters\". Experts suggest that the most sustainable garment is the one already in your wardrobe, so buying fewer, better items and wearing them for longer may be the simplest solution of all."], "q": [{"q": "What is the main characteristic of fast fashion?", "o": ["It sells only high-quality clothes.", "It is produced only in small workshops.", "It depends on customers who keep clothes for years.", "It makes trendy clothes cheaply and in large numbers."], "a": 3, "e": "Hız ve hacim; çok sayıda ucuz tasarım."}, {"q": "What problem is mentioned about synthetic fabrics?", "o": ["They need more water than cotton.", "They release plastic fibres when washed.", "They are always unsafe to wear.", "They cost too much to make."], "a": 1, "e": "Yıkamada mikro plastik lifler salıyorlar."}, {"q": "Why is it hard for shoppers to know who made their clothes?", "o": ["Companies refuse to sell online.", "Factories only work at night.", "Labels are written in foreign languages.", "The supply chains are long and complicated."], "a": 3, "e": "Tedarik zinciri uzun ve karmaşık."}, {"q": "What do experts suggest in the last paragraph?", "o": ["Giving up second-hand shops", "Buying fewer clothes and wearing them longer", "Choosing the cheapest brands", "Washing clothes more often"], "a": 1, "e": "Daha az, daha iyi ve uzun süre giymek."}]}, {"id": "garden7", "t": "Gardens in the Sky", "lv": "B2", "g": [["rooftop", "çatı katı terası"], ["produce", "ürün, sebze-meyve"], ["urban", "kentsel"], ["yield", "verim; ürün vermek"], ["insulation", "yalıtım"], ["community", "topluluk"]], "p": ["In cities where space is expensive, it is surprising to see lettuces growing between the chimneys. Yet rooftop gardens are becoming increasingly common, from restaurants that grow their own herbs to apartment blocks with vegetable beds on the roof.", "The benefits go beyond fresh produce. Plants absorb heat, so a green roof can keep a building cooler in summer and warmer in winter, reducing the cost of air conditioning and heating. They also soak up rainwater, which helps cities cope with heavy storms, and they provide a home for insects such as bees.", "There are practical difficulties, however. A garden of soil and water is heavy, so the building must be strong enough to support it. Winds can be fierce at that height, and a high yield requires careful watering. For these reasons, many projects begin with lightweight containers rather than deep beds.", "Perhaps the greatest value is social. In one neighbourhood, residents who had never spoken to each other started to meet on the roof every weekend. They now share the harvest, swap recipes and organise summer parties. As one gardener told a reporter, \"We came for the tomatoes, but we stayed for the people.\""], "q": [{"q": "How can a green roof help a building?", "o": ["It makes the building taller.", "It stops all rain from entering.", "It can lower heating and cooling costs.", "It replaces the need for windows."], "a": 2, "e": "Bina yazın serin, kışın sıcak kalır."}, {"q": "Why do many projects start with lightweight containers?", "o": ["Deep beds of soil are too heavy for many buildings.", "Containers are more beautiful.", "Plants grow faster in them.", "The council requires them."], "a": 0, "e": "Toprak ve su ağırdır."}, {"q": "What happened in one neighbourhood?", "o": ["Neighbours argued about the harvest.", "The roof had to be closed.", "Residents who did not know each other became friends.", "The garden was sold to a restaurant."], "a": 2, "e": "Birbirini tanımayan sakinler dost oldu."}, {"q": "What does the quotation at the end suggest?", "o": ["People value the social side as much as the food.", "The tomatoes were of poor quality.", "The gardener wanted to leave.", "The reporter disliked the project."], "a": 0, "e": "\"We came for the tomatoes, but we stayed for the people.\""}]}, {"id": "detox7", "t": "Switching Off", "lv": "B2", "g": [["detox", "arınma"], ["notification", "bildirim"], ["distraction", "dikkat dağıtıcı"], ["boundary", "sınır"], ["constantly", "sürekli"], ["rewarding", "tatmin edici"]], "p": ["Last month, I put my phone in a drawer for a whole weekend. I had read an article about \"digital detox\", and I was curious to see whether I could survive without my devices for forty-eight hours. The answer, it turned out, was complicated.", "The first morning was strange. I kept reaching for my pocket, and I felt a kind of restlessness I could not explain. Without notifications, the day seemed much longer. But by the afternoon, I had started a book I had been ignoring for months, and I noticed that I was able to read for an hour without stopping.", "Not everything was easy. I missed several messages from friends, and my sister, who could not reach me, became quite worried. Without a map, I also got lost on the way to a café, and I had to ask a stranger for directions, something I had not done in years.", "Would I do it again? Probably, but not completely. Instead of cutting myself off, I have decided to set boundaries: no phone at meals, no notifications after nine in the evening and one phone-free day a month. Technology is useful, but it should serve us, not the other way round."], "q": [{"q": "How did the writer feel on the first morning?", "o": ["Calm and relaxed", "Restless without his phone", "Angry with his sister", "Proud of himself"], "a": 1, "e": "Sürekli cebine uzanıyor, huzursuzdu."}, {"q": "What positive result did he notice by the afternoon?", "o": ["He finished his work earlier.", "He made new friends.", "He found the café at once.", "He could read for an hour without stopping."], "a": 3, "e": "Bir saat kesintisiz kitap okudu."}, {"q": "Why did his sister become worried?", "o": ["He had lost his keys.", "She could not contact him.", "He did not visit her.", "He had changed his number."], "a": 1, "e": "Ona ulaşamadı."}, {"q": "What has the writer decided to do?", "o": ["Never use a phone again", "Buy a new phone", "Delete all his messages", "Set limits on his phone use"], "a": 3, "e": "Yemekte telefon yok, 9'dan sonra bildirim yok, ayda bir telefonsuz gün."}]}, {"id": "fail7", "t": "Learning from Failure", "lv": "B2", "g": [["setback", "aksilik"], ["resilience", "dayanıklılık"], ["perfectionism", "mükemmeliyetçilik"], ["stigma", "damga, ayıp sayılma"], ["persevere", "pes etmeden sürdürmek"], ["feedback", "geri bildirim"]], "p": ["In many cultures, failure is considered something to hide. Students are rewarded for correct answers, and a bad mark can feel like a personal disaster. Yet researchers who study achievement increasingly argue that the fear of failure may be doing more harm than failure itself.", "One university has started an unusual experiment: a \"failure CV\", on which students list the projects that did not work out, the jobs they were refused and the exams they did not pass. Alongside each entry, they write what they learnt. The idea is not to feel sad about the past, but to show that setbacks are a normal part of any career.", "Psychologists describe a quality called resilience, the ability to recover after a difficulty. According to their research, resilient people do not avoid mistakes; they treat them as information. When something goes wrong, they ask, \"What can I change?\" rather than \"What is wrong with me?\"", "This does not mean that we should look for failure. But perfectionism, the belief that everything must be done without error, can stop people from trying new things at all. As the saying goes, a ship is safe in the harbour, but that is not what ships are for."], "q": [{"q": "What do researchers increasingly argue about fear of failure?", "o": ["It can be more harmful than failure itself.", "It helps students work harder.", "It is disappearing in schools.", "It only affects young children."], "a": 0, "e": "Başarısızlık korkusu bazen başarısızlıktan daha zararlı."}, {"q": "What is the purpose of a \"failure CV\"?", "o": ["To help students find jobs faster", "To punish students who fail", "To show that setbacks are normal and teach lessons", "To list the best projects only"], "a": 2, "e": "Aksilikler normal ve her birinden ders çıkar."}, {"q": "How do resilient people react to mistakes?", "o": ["They treat them as information.", "They avoid taking any risks.", "They blame themselves.", "They ignore them."], "a": 0, "e": "Hataları bilgi olarak görürler."}, {"q": "What does the writer say about perfectionism?", "o": ["It leads to better exam results.", "It is the key to resilience.", "It can prevent people from trying new things.", "It only exists in schools."], "a": 2, "e": "Yeni şeyler denemekten alıkoyabilir."}]}, {"id": "flat7", "t": "Looking for a Flat", "lv": "B1", "g": [["landlord", "ev sahibi"], ["rent", "kira"], ["deposit", "depozito"], ["furnished", "eşyalı"], ["contract", "sözleşme"], ["neighbourhood", "semt, mahalle"]], "p": ["When Deniz got a place at university in Ankara, he had to find a flat. His parents advised him to start looking early, so he spent two weekends visiting different apartments with his uncle.", "The first flat was big and cheap, but it was a long way from the university, and the neighbourhood was very noisy. The second one was furnished and close to the metro, yet the rent was higher than Deniz could afford. He was beginning to lose hope when his uncle noticed a small advertisement in a shop window.", "The third flat was perfect. It had two bedrooms, so Deniz could share it with a friend and divide the rent. The landlord, an elderly teacher, asked for a deposit of one month's rent and showed them a contract that explained everything clearly. \"Read it carefully before you sign,\" he said.", "Deniz moved in the following Saturday. On his first evening, he cooked pasta for his new flatmate and his uncle, and they celebrated with tea on the balcony. \"It's not a palace,\" Deniz said, \"but it's ours.\""], "q": [{"q": "Why did Deniz reject the first flat?", "o": ["It was too small.", "The landlord was unfriendly.", "It had no furniture.", "It was far away and in a noisy area."], "a": 3, "e": "Uzak ve gürültülü bir semtteydi."}, {"q": "What was wrong with the second flat?", "o": ["It was far from the metro.", "The rent was too high for him.", "It was unfurnished.", "It was on the ground floor."], "a": 1, "e": "Kira karşılayabileceğinden yüksekti."}, {"q": "How did Deniz find the third flat?", "o": ["A friend recommended it.", "He found it online.", "The university suggested it.", "His uncle saw an advertisement."], "a": 3, "e": "Amcası vitrindeki ilanı gördü."}, {"q": "What does \"It's not a palace, but it's ours\" suggest?", "o": ["He is disappointed.", "He is happy with a simple home.", "He wants a bigger flat.", "He is angry with his uncle."], "a": 1, "e": "Sade ama kendisinin olan evden memnun."}]}, {"id": "rain7", "t": "A Rainy Holiday", "lv": "B1", "g": [["forecast", "hava tahmini"], ["board game", "kutu oyunu"], ["cosy", "sıcak, rahat"], ["cabin", "kulübe"], ["puddle", "su birikintisi"], ["make the best of", "durumdan en iyi şekilde yararlanmak"]], "p": ["We had been looking forward to our holiday in the mountains for months. The forecast said sunshine all week, so we packed shorts, sun cream and hats. When we arrived at the little cabin on Saturday, however, it was pouring with rain.", "It rained on Sunday, and it rained on Monday. By Tuesday, my brother and I were bored. We had finished all our books, and the only things in the cabin were an old radio and a box of board games. Dad, who hates losing, suggested a family tournament.", "To my surprise, it turned out to be fun. We played until midnight, and Mum, who nobody expected to win, beat us all. On Wednesday, we put on raincoats and went for a walk anyway. We jumped in puddles, found mushrooms and returned home soaked but laughing.", "On Thursday, the sun finally came out. We climbed to the top of the hill and had a picnic. People often ask if the holiday was spoiled by the weather. I tell them it was one of the best we have ever had, because we learnt how to make the best of every situation."], "q": [{"q": "What did the family pack for the holiday?", "o": ["warm coats", "raincoats", "clothes for hot weather", "skiing equipment"], "a": 2, "e": "Şort, güneş kremi ve şapka."}, {"q": "Why did the writer and his brother get bored?", "o": ["They had no more books to read.", "They did not like the cabin.", "Their parents were angry.", "There was no radio."], "a": 0, "e": "Kitaplar bitmişti."}, {"q": "Who won the family tournament?", "o": ["the writer's father", "the writer", "the writer's mother", "his brother"], "a": 2, "e": "Kimsenin beklemediği anne kazandı."}, {"q": "How does the writer feel about the holiday?", "o": ["It was one of their best holidays.", "It was completely spoiled.", "He regrets going to the mountains.", "He wants to go in winter next time."], "a": 0, "e": "\"one of the best we have ever had\"."}]}, {"id": "reunion7", "t": "The Family Reunion", "lv": "B1", "g": [["reunion", "aile buluşması"], ["relative", "akraba"], ["generation", "nesil"], ["gather", "toplanmak"], ["album", "albüm"], ["toast", "kadeh kaldırmak"]], "p": ["Every summer, my father's family gathers at my grandparents' house in the countryside. It is not a small event: more than forty relatives come, from babies to my great-aunt, who is ninety-one years old.", "The morning is always busy. The women cook huge pots of food in the kitchen, while the men put tables and chairs under the apple trees. Children run around, and my little cousins usually fall into the stream at least once. My job is to take photographs of everybody, which is not easy when nobody stays still.", "After lunch, my grandfather brings out an old photo album. We look at pictures of my parents when they were children, and everyone laughs at their funny clothes. My great-aunt tells stories about the village sixty years ago, when there was no electricity, and the young ones listen carefully.", "In the evening, my grandfather makes a short speech and lifts his glass. \"To the family,\" he says, \"and to the next generation.\" I look around the table at all the faces and feel lucky. I know that, wherever I live in the future, this is the place I will always come back to."], "q": [{"q": "How many people usually come to the reunion?", "o": ["about ten", "more than forty", "about twenty", "nearly a hundred"], "a": 1, "e": "Kırktan fazla akraba."}, {"q": "What is the writer's job during the morning?", "o": ["cooking", "arranging the tables", "looking after the children", "taking photographs"], "a": 3, "e": "Herkesin fotoğrafını çekmek."}, {"q": "What does the great-aunt talk about?", "o": ["her own children", "life in the village long ago", "her favourite recipes", "the weather"], "a": 1, "e": "Altmış yıl önceki köy hayatı."}, {"q": "How does the writer feel at the end?", "o": ["tired and bored", "sad about leaving", "worried about the future", "grateful and attached to the place"], "a": 3, "e": "Şanslı hissediyor ve her zaman geri dönecek."}]}, {"id": "school7", "t": "The New Student", "lv": "B1", "g": [["timetable", "ders programı"], ["locker", "dolap"], ["shy", "utangaç"], ["break", "teneffüs"], ["settle in", "alışmak"], ["welcome", "karşılamak"]], "p": ["On Monday morning, Zeynep walked through the gates of her new school feeling very nervous. Her family had moved to a different city, and she did not know anybody. Her heart was beating so fast that she could hardly breathe.", "In the office, the secretary gave her a timetable, a map of the building and the key to a locker. \"Your form teacher, Mr Kaya, will meet you in room 12,\" she said with a smile. Zeynep got lost twice before she finally found the room.", "Mr Kaya introduced her to the class and asked a girl called Lale to look after her. At break, Lale showed her the canteen and told her which teachers were strict. Zeynep was shy at first, but when Lale said that she also loved painting, they started talking about their favourite artists.", "By Friday, Zeynep had stopped feeling like a stranger. She had joined the art club, learnt where everything was and been invited to Lale's birthday party. \"I was so worried on Monday,\" she told her mother at dinner. \"Now I can't believe how quickly it happened.\""], "q": [{"q": "How did Zeynep feel on Monday morning?", "o": ["very nervous", "excited and happy", "tired", "angry"], "a": 0, "e": "Çok gergindi."}, {"q": "What did the secretary give Zeynep?", "o": ["a uniform and some books", "a list of teachers", "a timetable, a map and a locker key", "an invitation"], "a": 2, "e": "Ders programı, harita ve dolap anahtarı."}, {"q": "What did Zeynep and Lale have in common?", "o": ["They both loved painting.", "They lived in the same street.", "They had the same teacher.", "They were in the same club."], "a": 0, "e": "İkisi de resim yapmayı seviyor."}, {"q": "How did Zeynep feel by Friday?", "o": ["still lost", "worried about the party", "more comfortable at school", "unwilling to return"], "a": 2, "e": "Artık yabancı hissetmiyordu."}]}, {"id": "wallet7", "t": "The Lost Wallet", "lv": "B1", "g": [["wallet", "cüzdan"], ["pavement", "kaldırım"], ["honest", "dürüst"], ["reward", "ödül"], ["owner", "sahip"], ["police station", "karakol"]], "p": ["One cold evening in November, Kerem was walking home from work when he noticed something dark on the pavement. It was a brown leather wallet. He looked around, but the street was empty.", "Inside, there was a lot of money, some cards and a student ID with a name: Aylin Demir. There was no phone number, but Kerem found a picture of a young woman with a little dog. He thought for a moment. The money would have been very useful, because he was saving for a new bike, but he knew it was not his.", "The next morning, he took the wallet to the nearest police station. The officer wrote down his details and thanked him. \"Honest people are not as common as you might think,\" she said. Kerem shrugged and went to work.", "Two days later, he received a call. It was Aylin, who had been crying for hours before the police contacted her. She wanted to give him a reward, but Kerem refused. \"Just be more careful next time,\" he said with a smile. A week later, a small package arrived at his door: a box of chocolates and a card that said, \"Thank you for being kind.\""], "q": [{"q": "What did Kerem find inside the wallet?", "o": ["only a phone number", "a bus ticket", "a key", "money, cards and a student ID"], "a": 3, "e": "Para, kartlar ve öğrenci kimliği."}, {"q": "Why did Kerem not keep the money?", "o": ["He was afraid of the police.", "He knew it belonged to someone else.", "He did not need money.", "The wallet was empty."], "a": 1, "e": "Onun olmadığını biliyordu."}, {"q": "What did Kerem say when Aylin offered a reward?", "o": ["He accepted it happily.", "He asked for more.", "He did not answer.", "He refused it."], "a": 3, "e": "Reddetti."}, {"q": "How did Aylin thank him in the end?", "o": ["She invited him to dinner.", "She sent chocolates and a card.", "She gave him some money.", "She called the police again."], "a": 1, "e": "Çikolata ve teşekkür kartı gönderdi."}]}, {"id": "bike7", "t": "Learning to Ride a Bike", "lv": "B1", "g": [["balance", "denge"], ["stabiliser", "destek tekerleği"], ["wobble", "sallanmak"], ["pedal", "pedal çevirmek"], ["helmet", "kask"], ["proud", "gururlu"]], "p": ["My grandfather decided to learn to ride a bicycle at the age of sixty-eight. When he told us, we thought he was joking. He had lived all his life in a village in the mountains, where people travelled by donkey or on foot, and he had never even sat on a bike.", "My brother and I offered to teach him in the empty car park near our house. Grandfather put on a helmet that was far too small, and we held the back of the seat. At first, he wobbled so much that he fell off after three metres. \"It's harder than it looks,\" he said, laughing.", "We practised every evening for two weeks. Slowly, he learnt that the secret is not to look at the ground, but straight ahead, and to keep pedalling. On the twelfth day, I let go of the seat without telling him. He rode twenty metres alone before he noticed!", "Today, Grandfather cycles to the market every Saturday. Our neighbours wave when they see him, and he waves back with a big smile. \"You are never too old to learn,\" he tells everybody. We are very proud of him."], "q": [{"q": "Why did the family think he was joking?", "o": ["He was too ill.", "He already had a bike.", "He had never ridden a bike before.", "He lived in a city."], "a": 2, "e": "Hayatında hiç bisiklete binmemişti."}, {"q": "What was the problem with the helmet?", "o": ["It was too small.", "It was too heavy.", "It was broken.", "It was not his."], "a": 0, "e": "\"far too small\""}, {"q": "What happened on the twelfth day?", "o": ["He fell off again.", "He bought a bike.", "He rode alone without knowing it.", "He cycled to the market."], "a": 2, "e": "Selenin tutulmadığını fark etmeden 20 metre sürdü."}, {"q": "What is the grandfather's message to people?", "o": ["People can learn at any age.", "Cycling is only for the young.", "Donkeys are better than bikes.", "Markets are best visited on foot."], "a": 0, "e": "\"You are never too old to learn.\""}]}, {"id": "bank7", "t": "Opening a Bank Account", "lv": "B1", "g": [["account", "hesap"], ["passport", "pasaport"], ["form", "form"], ["cash machine", "bankamatik"], ["balance", "bakiye"], ["interest", "faiz"]], "p": ["When Cem started his first job, his manager told him he needed a bank account so the company could pay his salary. He had never been inside a bank before, so he asked his sister Gül for advice.", "On Saturday morning, they went to a branch near the station. Cem took his passport and a proof of address, as Gül had told him. A friendly assistant gave him a form to fill in and explained the different types of account. \"A student account has no fees,\" she said, \"but you can only use it until you are twenty-five.\"", "Cem chose a normal current account with a card. The assistant explained that he could use the cash machine at any time, but he should never tell anyone his PIN. She also showed him how to check his balance on the phone.", "Within a week, his card arrived in the post, and at the end of the month, his first salary was in the account. Cem felt very grown-up. \"Now I just have to learn not to spend it all in the first week,\" he joked."], "q": [{"q": "Why did Cem need a bank account?", "o": ["To save for a holiday", "So his company could pay his salary", "To get a student card", "Because his sister asked him to"], "a": 1, "e": "Maaşın yatırılması için."}, {"q": "What did Cem take to the bank?", "o": ["his old bank card", "his employer", "a letter from his manager", "his passport and proof of address"], "a": 3, "e": "Pasaport ve adres belgesi."}, {"q": "What did the assistant tell him about his PIN?", "o": ["Write it on the card.", "Never tell it to anybody.", "Change it every day.", "Share it with his sister."], "a": 1, "e": "PIN'ini kimseye söylememeli."}, {"q": "What does Cem mean by his final joke?", "o": ["He will save all his salary.", "He wants a second account.", "He has lost his card.", "He may spend his money too quickly."], "a": 3, "e": "İlk haftada hepsini harcama riski."}]}, {"id": "cook7", "t": "My First Dinner Party", "lv": "B1", "g": [["guest", "konuk"], ["recipe", "tarif"], ["chop", "doğramak"], ["burn", "yanmak"], ["serve", "servis etmek"], ["dessert", "tatlı"]], "p": ["Last Saturday, I invited six friends to dinner. It was the first time I had cooked for so many people, and I wanted everything to be perfect. I chose a simple menu: tomato soup, chicken with rice and an apple cake.", "I started cooking at two o'clock. The soup was easy, and the cake smelt wonderful. Then I made my first mistake: I forgot to set the timer for the chicken, and when I opened the oven, one side was nearly black. I felt like crying.", "My friend Burcu, who arrived early, saved the day. She cut off the burnt parts and covered the chicken with a delicious sauce made of garlic and lemon. By the time the guests came, nobody could tell that anything had gone wrong.", "We ate, laughed and talked until midnight. Everyone said the cake was the best part of the meal. I learnt two things that evening: always use a timer, and never be too proud to ask for help."], "q": [{"q": "What was the writer's mistake?", "o": ["She forgot to set a timer for the chicken.", "She invited too many guests.", "She chose a difficult menu.", "She forgot the cake."], "a": 0, "e": "Tavuk için zamanlayıcıyı kurmadı."}, {"q": "How did Burcu help?", "o": ["She cooked a new chicken.", "She served the guests.", "She hid the burnt parts with a sauce.", "She washed the dishes."], "a": 2, "e": "Yanık yerleri kesip sosla kapladı."}, {"q": "Which part of the meal was the most popular?", "o": ["the cake", "the soup", "the chicken", "the rice"], "a": 0, "e": "Herkes keki en güzel kısım buldu."}, {"q": "What did the writer learn?", "o": ["never to cook for guests", "to buy ready meals", "to use a timer and to accept help", "to start cooking earlier"], "a": 2, "e": "Zamanlayıcı kullan, yardım iste."}]}, {"id": "volun7", "t": "A Day at the Animal Shelter", "lv": "B1", "g": [["shelter", "barınak"], ["stray", "sahipsiz"], ["volunteer", "gönüllü"], ["adopt", "sahiplenmek"], ["feed", "beslemek"], ["cage", "kafes"]], "p": ["Every other Saturday, I work as a volunteer at an animal shelter on the edge of our town. The shelter looks after about sixty dogs and cats, most of which were found as strays on the street.", "My day begins at nine. First, I help to feed the animals and clean their cages. Then I take the dogs for a walk in the field behind the shelter. They are always very excited, and some of them pull so hard that I almost fall over!", "In the afternoon, I sit with the cats. Many of them are shy because they have been treated badly. I talk to them quietly and wait until they come to me. It can take weeks, but it is wonderful when a cat finally climbs onto your lap.", "The best day is when an animal is adopted. Last week, a family took home a little brown dog called Pepper. Everyone at the shelter clapped as they left. I was happy for him, but I admit I had tears in my eyes."], "q": [{"q": "Where do most of the animals come from?", "o": ["They were born at the shelter.", "They were bought from shops.", "They came from farms.", "They were found on the street."], "a": 3, "e": "Çoğu sokakta sahipsiz bulunmuş."}, {"q": "What does the writer do in the morning?", "o": ["trains the cats", "feeds animals and cleans cages", "answers the phone", "takes photographs"], "a": 1, "e": "Hayvanları besler, kafesleri temizler."}, {"q": "Why are many of the cats shy?", "o": ["They are very old.", "They are ill.", "They do not like people at all.", "They have been treated badly."], "a": 3, "e": "Kötü muamele görmüşler."}, {"q": "How did the writer feel when Pepper left?", "o": ["angry", "happy but emotional", "bored", "worried"], "a": 1, "e": "Mutlu ama gözleri doldu."}]}, {"id": "mobile7", "t": "A New Phone", "lv": "B1", "g": [["screen", "ekran"], ["battery", "pil"], ["upgrade", "yükseltmek"], ["contract", "sözleşme"], ["compare", "karşılaştırmak"], ["worth", "değer"]], "p": ["My old phone finally died last week. The screen had been cracked for months, and the battery lasted only two hours. I knew I needed a new one, but I had no idea which to choose, because there are so many different models.", "First, I asked my friends. Everyone recommended something different, and each of them said that their own phone was the best. Then I read some reviews online and made a list of the features I really needed: a good camera, a long-lasting battery and a reasonable price.", "I went to three shops to compare prices. In the first, a salesman tried to persuade me to buy the most expensive model, which I did not need. In the second, the staff were more helpful, and they explained the difference between a contract and paying all at once. In the third, I found exactly what I wanted at a discount.", "I paid, took my new phone home and spent the evening copying my photos. It works perfectly, and I am glad I did not rush. My advice: decide what you need before you go shopping, and do not let anybody sell you more than that."], "q": [{"q": "Why did the writer need a new phone?", "o": ["She lost it on a bus.", "Her friends all had new ones.", "The old one was broken and the battery was poor.", "It was stolen."], "a": 2, "e": "Ekran çatlak, pil iki saat."}, {"q": "What did she do before going shopping?", "o": ["She made a list of features she needed.", "She asked her parents for money.", "She sold her old phone.", "She bought a protective case."], "a": 0, "e": "İhtiyaç duyduğu özelliklerin listesini yaptı."}, {"q": "What was wrong with the first shop?", "o": ["The prices were not shown.", "The shop was closed.", "The salesman pushed an expensive model.", "The staff did not speak to her."], "a": 2, "e": "Satıcı pahalı modeli satmaya çalıştı."}, {"q": "What is the writer's advice?", "o": ["Decide what you need before shopping.", "Always buy the cheapest phone.", "Ask friends to choose for you.", "Never buy from a shop."], "a": 0, "e": "Ne istediğine önceden karar ver."}]}];var T={"hotel7": {"p": ["Geçen bahar kuzenim Ece ile hafta sonunu İzmir'de geçirmeye karar verdik. Planlamak için yalnızca bir haftamız vardı, o yüzden internette otel aradık. Yüzlerce seçenek vardı ve başta karar vermek zordu.", "Ece en ucuz odayı istiyordu ama ben önce yorumları okumayı tercih ettim. Bir otel çok ucuzdu, fakat birçok misafir odaların gürültülü olduğunu ve kahvaltının dahil olmadığını yazmıştı. Bir diğeri biraz daha pahalıydı ama insanlar personelin sıcakkanlı olduğunu ve harika bir deniz manzarası bulunduğunu söylüyordu. İkincisini seçtik.", "Ödeme yapmadan önce iptal kurallarına baktım. Rezervasyon varış tarihimizden iki gün öncesine kadar ücretsiz iptal edilebiliyordu, ondan sonra paramızın yalnızca yarısı geri verilecekti. Bu adil göründü; bu yüzden rezervasyonu onayladık ve birkaç dakika içinde bir e-posta aldık.", "Hafta sonu mükemmeldi. Odamız dördüncü kattaydı ve her sabah balkonda çay içip tekneleri izledik. Sonunda ben de kısa bir yorum yazdım. Bence yorumlar yararlıdır, çünkü sonraki misafirler, tıpkı bizim başkalarının deneyimlerinden öğrendiğimiz gibi, bizim deneyimimizden öğrenebilir."], "q": [{"q": "Yazar neden ikinci oteli seçti?", "o": ["İnternetteki en ucuz otelle idi.", "Misafirler personeli ve manzarayı övüyordu.", "Ece daha önce orada kalmıştı.", "Kahvaltı fiyata dahildi."]}, {"q": "Varıştan bir gün önce iptal ederlerse ne olur?", "o": ["Hiçbir şey ödemezler.", "Bütün paralarını kaybederler.", "Başka bir oda ayırtmaları gerekir.", "Paranın yarısını geri alırlar."]}, {"q": "Yazar hafta sonundan sonra ne yaptı?", "o": ["Ece'ye e-posta gönderdi.", "Otel hakkında kendi görüşünü yazdı.", "Para iadesi istedi.", "Aynı odayı yeniden ayırttı."]}, {"q": "Yazarın yorumlar hakkındaki görüşü nedir?", "o": ["Genellikle dürüst değildir.", "Okumak için çok uzundur.", "Yalnızca ucuz oteller için önemlidir.", "Gelecekteki misafirlerin karar vermesine yardım eder."]}]}, "doctor7": {"p": ["Pazartesi sabahı Burak boğaz ağrısı ve baş ağrısıyla uyandı. Ateşi yoktu, bu yüzden sadece soğuk algınlığı sandı. Ancak akşama doğru kendini çok daha kötü hissetti ve annesi ertesi gün için Dr. Aksoy'dan randevu aldı.", "Bekleme odasında beş hasta daha vardı. Burak yirmi dakika beklemek zorunda kaldı; bunu sıkıcı bulduğu için bahçelerle ilgili eski bir dergi okudu. Sonunda hemşire adını çağırdı.", "Dr. Aksoy belirtilerini sordu ve boğazına baktı. \"Enfeksiyonun var,\" dedi. \"Sana bir ilaç reçetesi yazacağım. Günde üç kez, yemeklerden sonra al ve bol su iç.\" Ayrıca üç gün evde kalmasını ve tamamen iyileşene kadar futbol antrenmanına gitmemesini söyledi.", "Burak reçeteyi evinin yakınındaki eczaneye götürdü. Eczacı, ilacın onu biraz uykulu yapabileceğini, bu yüzden spor yapmaması gerektiğini açıkladı. Dört gün sonra iyileşmişti ve okula dönmekten mutluydu. \"Bir dahaki sefere,\" dedi, \"doktora daha erken giderim.\""], "q": [{"q": "Burak'un annesi neden doktoru aradı?", "o": ["Burak gün içinde daha kötü hissetti.", "Pazartesi günü yüksek ateşi vardı.", "Futbol antrenmanını kaçırmıştı.", "Okuldan erken ayrılmak istiyordu."]}, {"q": "Burak bekleme odasında ne yaptı?", "o": ["Hemşireyle konuştu.", "Telefonunda oynadı.", "Bir dergi okudu.", "Uyuyakaldı."]}, {"q": "Doktor Burak'a ne yapmasını söyledi?", "o": ["İlaç almasını ve bir süre antrenmandan uzak durmasını.", "Daha fazla tetkik için hastaneye gitmesini.", "Üç gün hiçbir şey yememesini.", "Ertesi gün okula dönmesini."]}, {"q": "Burak sonunda ne söylüyor?", "o": ["Bir daha futbola gitmeyecek.", "Eczacıya güvenmiyor.", "Gelecekte doktora daha erken gidecek.", "Doktorların çok yavaş olduğunu düşünüyor."]}]}, "driving7": {"p": ["Selin on sekiz yaşına girince araba kullanmayı öğrenmeye karar verdi. Ailesi memnun oldu, çünkü onu her yere götürmekten bıkmışlardı. Evinin yakınındaki bir sürücü kursuna yazıldı ve ilk dersini takip eden pazartesi aldı.", "Eğitmeni Bay Polat, sesini hiç yükseltmeyen sakin bir adamdı. İlk derste boş bir otoparkta çalıştılar. Selin arabayı yumuşakça hareket ettirmeyi zor buldu ve motor üç kez durdu. Buna güldü ama içten içe gergindi.", "On dersten sonra kendini daha güvende hissetti ve gerçek yollarda sürmeye başladı. En zor kısım döner kavşaklardı, çünkü ne zaman girmesi gerektiğini bilemiyordu. Bay Polat her seferinde \"Sağa bak ve bir boşluk bekle,\" derdi. Yavaş yavaş kolaylaştı.", "Mart ayında teorik sınava girdi ve ilk denemede geçti. Direksiyon sınavı daha zordu: küçük bir hata yaptı ve bir ay sonra yeniden denemek zorunda kaldı. Bu sefer sakindi ve sınav görevlisi sonunda gülümsedi. \"Geçtiniz,\" dedi. Selin eve giderken bir an bile gülümsemekten vazgeçemedi."], "q": [{"q": "Selin ilk derste nasıl hissetti?", "o": ["Otoparktan sıkılmıştı.", "Bay Polat'a kızgındı.", "Tamamen rahattı.", "Kaygılıydı ama gülmeye çalıştı."]}, {"q": "Selin için yolda en zor olan neydi?", "o": ["Motoru çalıştırmak", "Döner kavşağa ne zaman gireceğine karar vermek", "Dar yerlere park etmek", "Geceleri sürmek"]}, {"q": "İlk direksiyon sınavında ne oldu?", "o": ["Kolayca geçti.", "Sınavı iptal etti.", "Belgelerini unuttu.", "Bir hata yaptı ve kaldı."]}, {"q": "Selin sonunda nasıl hissetti?", "o": ["hayal kırıklığına uğramış", "çok sevinçli", "endişeli", "utanmış"]}]}, "festival7": {"p": ["Her nisan ayında kasabamız üç gün süren bir bahar şenliği düzenler. Yakın köylerden insanlar gelir ve ana cadde trafiğe kapatılır. Biz çocuklar için yılın en güzel zamanıdır.", "Şenlik cuma günü bir geçit töreniyle başlar. Her okuldan öğrenciler renkli kostümlerle caddede yürür ve bir bando geleneksel müzik çalar. Geçen yıl sınıfım çiçek olarak giyindi; arı olan küçük kardeşim kanatlarını bir hafta boyunca çıkarmak istemedi!", "Cumartesi günü yerel yiyecekler, el yapımı oyuncaklar ve çiçekler satan tezgâhlar olur. Büyükannem her zaman ev yapımı reçelini satar ve genellikle öğlene kadar hepsi biter. Akşamları meydanda bir konser olur ve bütün kalabalık, sözleri bilmeseler bile, birlikte şarkı söyler.", "Şenlik pazar günü nehir kenarında bir piknikle sona erer. Aileler battaniyelerini getirir ve yemeklerini komşularıyla paylaşır. Bu geleneği seviyorum, çünkü kasabayı büyük bir aile gibi hissettiriyor. Nisan ayında bir gün bu çevrede olursanız, gelip görmelisiniz."], "q": [{"q": "Şenliğin ilk gününde ne olur?", "o": ["İnsanlar meydanda reçel satar.", "Aileler piknik yapar.", "Öğrenciler geçit töreninde yürür.", "Nehir kenarında konser verilir."]}, {"q": "Yazar küçük kardeşi hakkında ne söylüyor?", "o": ["Kostümünü çok sevdi.", "Kalabalıktan korktu.", "Geçit törenine katılmak istemedi.", "Bir tezgâhta çiçek sattı."]}, {"q": "Yazar pikniği neden seviyor?", "o": ["Yemek tezgâhlardakinden daha iyi.", "Şenliğin en kısa kısmı.", "İnsanları birbirine yakın hissettiriyor.", "Kimsenin bir şey getirmesi gerekmiyor."]}, {"q": "Metin kimler için yazılmış?", "o": ["kasabayı ziyaret edebilecek insanlar", "yazarın okulundaki öğrenciler", "belediye meclisi", "dükkân sahipleri"]}]}, "jobs7": {"p": ["Birçok öğrenci okurken biraz para kazanmak ister ve ben de bir istisna değilim. Geçen sonbahar cumartesileri ve haftada iki akşam bir kitabevinde çalışmaya başladım. Ücret yüksek değil ama işi beklediğimden çok seviyorum.", "Günüm saat dokuzda, müdürüm Bayan Yılmaz ile dükkânı açtığımızda başlar. Önce yeni kitapları raflara koyarız. Sonra müşterilerin aradıklarını bulmalarına yardım ederim. Bazıları çok nazik, ama bazıları bir kitabı hemen bulamadığımda sabırsızlanır.", "İş bana çok şey öğretti. Sakin kalmayı, dikkatle dinlemeyi ve zamanımı organize etmeyi öğrendim. Yine de çalışma ile dersleri dengelemek her zaman kolay değil. Sınavlardan önce Bayan Yılmaz'dan daha az vardiya istedim ve o da nazikçe kabul etti.", "Diğer öğrencilere tavsiyem, ders programlarına uyan bir iş aramalarıdır. Yarı zamanlı iş size deneyim kazandırır; bu da daha sonra tam zamanlı bir işe başvurduğunuzda işe yarar. Ama derslerinizin her zaman önce geldiğini unutmayın."], "q": [{"q": "Yazar ücret hakkında ne söylüyor?", "o": ["Beklediğinden çok daha yüksek.", "Düşük, ama iş keyifli.", "İşi almasının nedeni bu.", "Müşteri sayısına bağlı."]}, {"q": "İşin bazen zor olan yanı nedir?", "o": ["Dükkânı tek başına açmak", "Ağır kutuları taşımak", "Pazar günleri çalışmak", "Sabırsız müşteriler"]}, {"q": "Yazar sınavlardan önce ne yaptı?", "o": ["Bir ay işten ayrıldı.", "Daha az vardiya çalışmak istedi.", "Dükkânda ders çalıştı.", "Okuldaki programını değiştirdi."]}, {"q": "Yazarın öğrencilere tavsiyesi nedir?", "o": ["Okul yılında asla çalışmasınlar.", "En yüksek maaşı arasınlar.", "Mümkün olduğunca çok saat çalışsınlar.", "Derslerine uyan bir iş seçsinler."]}]}, "flight7": {"p": ["Daha önce hiç uçakla seyahat etmemiştim; bu yüzden ailem geçen yaz Antalya'ya giderken hem heyecanlı hem korkuyordum. Babam geç kalmaktan nefret ettiği için havalimanına üç saat erken vardık.", "Önce bagajlarımızı check-in kontuarına bıraktık ve biniş kartlarımızı aldık. Sonra güvenlik kontrolünden geçtik; orada kemerimi çıkarmam ve çantamı banda koymam gerekti. Hayal ettiğimden kolaydı ama annemin ne yapacağımı söylemek için orada olmasına sevindim.", "Kapıda neredeyse bir saat bekledik. Sonunda uçuşumuz anons edildiğinde kalbimin daha hızlı attığını hissettim. Uçağın içinde pencere kenarına oturdum, ablam da yanıma oturdu. Havalanırken kol dayanağını sıkıca tuttum. Ancak birkaç dakika sonra uçak bulutların içindeydi ve ben rahatlamaya başladım.", "Manzara inanılmazdı: deniz mavi bir halıya benziyordu ve arabalar minicikti. İniş yumuşaktı ve herkes alkışladı. \"O kadar korkunç muydu?\" diye sordu babam. Ben de mümkün olan en kısa sürede yeniden uçmak istediğimi söyledim."], "q": [{"q": "Aile havalimanına neden erken vardı?", "o": ["Yazarın babası geç kalmaktan hoşlanmıyor.", "Uçuş iptal edilmişti.", "Alışveriş yapmak istiyorlardı.", "Bagajları çok ağırdı."]}, {"q": "Yazar güvenlik kontrolü hakkında ne hissetti?", "o": ["Çok uzun sürdü.", "Korkutucuydu.", "Düşündüğünden daha basitti.", "Sıkıcıydı."]}, {"q": "Yazar havalanırken ne yaptı?", "o": ["Kol dayanağını sıkıca tuttu.", "Gözlerini kapatıp uyudu.", "Ablasıyla konuştu.", "Pencereden dışarı baktı."]}, {"q": "Yazar uçuşun sonunda nasıl hissetti?", "o": ["Bittiği için rahatlamıştı.", "Midesi bulanıyordu.", "Yakında tekrar uçmak istedi.", "Geldiğine pişmandı."]}]}, "fashion7": {"p": ["Bir sandviç fiyatına tişört kelimeye pazarlık gibi gelir, ama çok az alışverişçi bunun nasıl bu kadar ucuz olabildiğini sorar. Trend giysileri çok düşük fiyatlarla üreten iş modeli olan hızlı moda; hız ve hacme dayanır: bazı markalar artık her hafta binlerce yeni tasarım çıkarıyor.", "Sonuçları hatırı sayılır düzeydedir. Tek bir pamuklu tişört üretmek yaklaşık iki buçuk bin litre su gerektirebilir ve sentetik kumaşlar her yıkandığında küçük plastik lifler salar. Öte yandan ortalama bir giysi atılmadan önce yalnızca birkaç kez giyilir ve büyük kısmı çöp sahasında son bulur.", "İnsani maliyetler de var. Fiyatları düşük tutmak için birçok şirket, işçilerin çok az kazandığı ve koşulların güvensiz olabildiği fabrikalardan alım yapıyor. Tedarik zincirleri çok uzun ve karmaşık olduğu için iyi niyetli alışverişçiler bile kıyafetlerini kimin yaptığını bilmekte zorlanıyor.", "Cesaret verici biçimde tutumlar değişmeye başlıyor. İkinci el dükkânlar ve çevrim içi yeniden satış platformları hızla büyüyor, bazı gençler de kendilerini gururla \"thrifter\" olarak tanımlıyor. Uzmanlara göre en sürdürülebilir giysi zaten dolabınızdaki giysidir; bu yüzden daha az ama daha iyi parçalar satın alıp onları daha uzun giymek belki de en basit çözümdür."], "q": [{"q": "Hızlı modanın temel özelliği nedir?", "o": ["Yalnızca yüksek kaliteli giysiler satması.", "Yalnızca küçük atölyelerde üretilmesi.", "Giysileri yıllarca saklayan müşterilere dayanması.", "Trend giysileri ucuza ve çok sayıda üretmesi."]}, {"q": "Sentetik kumaşlarla ilgili hangi sorun belirtiliyor?", "o": ["Pamuktan daha çok su gerektiriyor.", "Yıkanınca plastik lifler salıyor.", "Giymek her zaman güvensiz.", "Üretimi çok pahalı."]}, {"q": "Alışverişçilerin kıyafetlerini kimin yaptığını bilmesi neden zor?", "o": ["Şirketler çevrim içi satmayı reddediyor.", "Fabrikalar yalnızca geceleri çalışıyor.", "Etiketler yabancı dilde yazılmış.", "Tedarik zincirleri uzun ve karmaşık."]}, {"q": "Uzmanlar son paragrafta ne öneriyor?", "o": ["İkinci el dükkânları bırakmak", "Daha az giysi alıp daha uzun giymek", "En ucuz markaları seçmek", "Giysileri daha sık yıkamak"]}]}, "garden7": {"p": ["Alanın pahalı olduğu şehirlerde, bacaların arasında büyüyen marulları görmek şaşırtıcıdır. Yine de çatı bahçeleri, kendi otlarını yetiştiren restoranlardan çatısında sebze yatakları olan apartmanlara kadar giderek yaygınlaşıyor.", "Faydaları taze üründen öteye geçer. Bitkiler ısıyı emer; bu yüzden yeşil bir çatı binayı yazın serin, kışın daha sıcak tutarak klima ve ısıtma maliyetini azaltabilir. Ayrıca yağmur suyunu emerek şehirlerin şiddetli fırtınalarla başa çıkmasına yardım eder ve arılar gibi böceklere yuva olur.", "Ancak pratik zorluklar da var. Toprak ve su dolu bir bahçe ağırdır, bu yüzden binanın onu taşıyacak kadar sağlam olması gerekir. O yükseklikte rüzgâr şiddetli olabilir ve yüksek verim, dikkatli sulama gerektirir. Bu nedenlerle birçok proje derin yataklar yerine hafif kaplarla başlar.", "Belki de en büyük değer toplumsal olandır. Bir mahallede birbiriyle hiç konuşmamış sakinler her hafta sonu çatıda buluşmaya başladı. Şimdi hasadı paylaşıyor, tarif değiş tokuş ediyor ve yaz partileri düzenliyorlar. Bir bahçıvanın muhabire dediği gibi: \"Domates için geldik, insanlar için kaldık.\""], "q": [{"q": "Yeşil çatı bir binaya nasıl yardımcı olabilir?", "o": ["Binayı daha yüksek yapar.", "Tüm yağmurun girmesini engeller.", "Isıtma ve soğutma maliyetini düşürebilir.", "Pencere ihtiyacını ortadan kaldırır."]}, {"q": "Birçok proje neden hafif kaplarla başlıyor?", "o": ["Derin toprak yatakları birçok bina için çok ağır.", "Kaplar daha güzel.", "Bitkiler onlarda daha hızlı büyür.", "Belediye bunu zorunlu kılıyor."]}, {"q": "Bir mahallede ne oldu?", "o": ["Komşular hasat yüzünden tartıştı.", "Çatı kapatılmak zorunda kaldı.", "Birbirini tanımayan sakinler arkadaş oldu.", "Bahçe bir restorana satıldı."]}, {"q": "Sondaki alıntı neyi düşündürüyor?", "o": ["İnsanlar toplumsal yanı yiyecek kadar değerli buluyor.", "Domateslerin kalitesi düşüktü.", "Bahçıvan ayrılmak istiyordu.", "Muhabir projeyi sevmedi."]}]}, "detox7": {"p": ["Geçen ay telefonumu bütün bir hafta sonu çekmeceye koydum. \"Dijital detoks\" hakkında bir makale okumuştum ve cihazlarım olmadan kırk sekiz saat dayanıp dayanamayacağımı merak ediyordum. Cevap, karmaşık çıktı.", "İlk sabah tuhaftı. Sürekli cebime uzanıyordum ve açıklayamadığım bir huzursuzluk hissediyordum. Bildirimler olmayınca gün çok daha uzun göründü. Ama öğleden sonra aylardır görmezden geldiğim bir kitaba başlamıştım ve durmadan bir saat okuyabildiğimi fark ettim.", "Her şey kolay değildi. Arkadaşlarımdan gelen birkaç mesajı kaçırdım ve bana ulaşamayan kız kardeşim oldukça endişelendi. Haritam olmadığı için bir kafeye giderken kayboldum ve yıllardır yapmadığım bir şeyi yaptım: bir yabancıya yol sormak zorunda kaldım.", "Tekrar yapar mıydım? Muhtemelen, ama tamamen değil. Kendimi dünyadan koparmak yerine sınırlar koymaya karar verdim: yemeklerde telefon yok, akşam dokuzdan sonra bildirim yok ve ayda bir telefonsuz gün. Teknoloji yararlıdır, ama bize hizmet etmeli, tersi değil."], "q": [{"q": "Yazar ilk sabah nasıl hissetti?", "o": ["Sakin ve rahat", "Telefonu olmadan huzursuz", "Kız kardeşine kızgın", "Kendisiyle gururlu"]}, {"q": "Öğleden sonra hangi olumlu sonucu fark etti?", "o": ["İşini daha erken bitirdi.", "Yeni arkadaşlar edindi.", "Kafeyi hemen buldu.", "Bir saat durmadan okuyabildi."]}, {"q": "Kız kardeşi neden endişelendi?", "o": ["Anahtarlarını kaybetmişti.", "Ona ulaşamadı.", "Onu ziyaret etmedi.", "Numarasını değiştirmişti."]}, {"q": "Yazar ne yapmaya karar verdi?", "o": ["Bir daha telefon kullanmamak", "Yeni telefon almak", "Tüm mesajlarını silmek", "Telefon kullanımına sınırlar koymak"]}]}, "fail7": {"p": ["Birçok kültürde başarısızlık saklanması gereken bir şey sayılır. Öğrenciler doğru cevaplar için ödüllendirilir ve kötü bir not kişisel bir felaket gibi hissettirebilir. Yine de başarıyı inceleyen araştırmacılar, başarısızlık korkusunun başarısızlığın kendisinden daha çok zarar verebileceğini giderek daha fazla savunuyor.", "Bir üniversite alışılmadık bir deney başlattı: \"başarısızlık özgeçmişi\". Öğrenciler bunda sonuçsuz kalan projelerini, reddedildikleri işleri ve kaldıkları sınavları listeliyor. Her kaydın yanına ne öğrendiklerini yazıyorlar. Amaç geçmiş için üzülmek değil, aksiliklerin her kariyerin normal bir parçası olduğunu göstermek.", "Psikologlar, zorluktan sonra toparlanabilme yeteneği olan dayanıklılık (resilience) denen bir özelliği tarif eder. Araştırmalarına göre dayanıklı insanlar hatalardan kaçınmaz; onları bilgi olarak görür. Bir şey ters gittiğinde \"Neyi değiştirebilirim?\" diye sorarlar, \"Bende ne yanlış?\" diye değil.", "Bu, başarısızlığı aramamız gerektiği anlamına gelmez. Ama her şeyin hatasız yapılması gerektiği inancı olan mükemmeliyetçilik, insanları yeni şeyler denemekten tamamen alıkoyabilir. Bir söz der ki, gemi limanda güvendedir ama gemiler bunun için yapılmaz."], "q": [{"q": "Araştırmacılar başarısızlık korkusu hakkında giderek ne savunuyor?", "o": ["Başarısızlığın kendisinden daha zararlı olabilir.", "Öğrencilerin daha çok çalışmasına yardım eder.", "Okullarda yok oluyor.", "Yalnızca küçük çocukları etkiler."]}, {"q": "\"Başarısızlık özgeçmişi\"nin amacı nedir?", "o": ["Öğrencilerin daha hızlı iş bulmasına yardım etmek", "Kalan öğrencileri cezalandırmak", "Aksiliklerin normal olduğunu göstermek ve ders çıkarmak", "Yalnızca en iyi projeleri listelemek"]}, {"q": "Dayanıklı insanlar hatalara nasıl tepki verir?", "o": ["Onları bilgi olarak görür.", "Hiç risk almaktan kaçınır.", "Kendilerini suçlar.", "Onları görmezden gelir."]}, {"q": "Yazar mükemmeliyetçilik hakkında ne diyor?", "o": ["Daha iyi sınav sonuçlarına yol açar.", "Dayanıklılığın anahtarıdır.", "İnsanları yeni şeyler denemekten alıkoyabilir.", "Yalnızca okullarda vardır."]}]}, "flat7": {"p": ["Deniz Ankara'da bir üniversite kazandığında kendine bir daire bulması gerekti. Ailesi erken aramaya başlamasını önerdi; bu yüzden amcasıyla iki hafta sonu farklı daireleri gezdi.", "İlk daire büyük ve ucuzdu ama üniversiteye uzaktı ve semt çok gürültülüydü. İkincisi eşyalı ve metroya yakındı, fakat kirası Deniz'in karşılayabileceğinden yüksekti. Umudunu kaybetmeye başlamıştı ki amcası bir dükkânın vitrininde küçük bir ilan fark etti.", "Üçüncü daire mükemmeldi. İki yatak odası vardı, bu yüzden Deniz bir arkadaşıyla paylaşıp kirayı bölebilecekti. Yaşlı bir öğretmen olan ev sahibi bir aylık kira tutarında depozito istedi ve her şeyi açıkça anlatan bir sözleşme gösterdi. \"İmzalamadan önce dikkatlice oku,\" dedi.", "Deniz ertesi cumartesi taşındı. İlk akşam yeni ev arkadaşı ve amcası için makarna pişirdi ve balkonda çayla kutladılar. \"Bir saray değil,\" dedi Deniz, \"ama bizim.\""], "q": [{"q": "Deniz ilk daireyi neden reddetti?", "o": ["Çok küçüktü.", "Ev sahibi samimiyetsizdi.", "Eşyası yoktu.", "Uzaktı ve gürültülü bir semtteydi."]}, {"q": "İkinci dairede sorun neydi?", "o": ["Metrodan uzaktı.", "Kira onun için çok yüksekti.", "Eşyasızdı.", "Zemin kattaydı."]}, {"q": "Deniz üçüncü daireyi nasıl buldu?", "o": ["Bir arkadaşı önerdi.", "İnternette buldu.", "Üniversite önerdi.", "Amcası bir ilan gördü."]}, {"q": "\"Saray değil ama bizim\" neyi düşündürüyor?", "o": ["Hayal kırıklığına uğramış.", "Sade bir evden memnun.", "Daha büyük bir daire istiyor.", "Amcasına kızgın."]}]}, "rain7": {"p": ["Dağlardaki tatilimizi aylardır sabırsızlıkla bekliyorduk. Hava tahmini bütün hafta güneş diyordu, bu yüzden şort, güneş kremi ve şapka koymuştuk. Ancak cumartesi küçük kulübeye vardığımızda yağmur bardaktan boşanırcasına yağıyordu.", "Pazar günü yağdı, pazartesi günü yağdı. Salıya gelince kardeşim ve ben sıkılmıştık. Bütün kitaplarımızı bitirmiştik ve kulübede yalnızca eski bir radyo ve bir kutu oyun vardı. Kaybetmekten nefret eden babam bir aile turnuvası önerdi.", "Şaşırtıcı biçimde eğlenceli çıktı. Gece yarısına kadar oynadık ve kimsenin kazanmasını beklemediği annem hepimizi yendi. Çarşamba günü yağmurluklarımızı giyip yine de yürüyüşe çıktık. Su birikintilerinde zıpladık, mantar bulduk ve sırılsıklam ama gülerek eve döndük.", "Perşembe günü güneş sonunda çıktı. Tepenin zirvesine tırmanıp piknik yaptık. İnsanlar sık sık tatilin havadan dolayı mahvolup olmadığını soruyor. Onlara, her durumdan en iyi şekilde yararlanmayı öğrendiğimiz için şimdiye kadarki en güzel tatillerimizden biri olduğunu söylüyorum."], "q": [{"q": "Aile tatil için ne hazırladı?", "o": ["kalın montlar", "yağmurluklar", "sıcak hava için kıyafetler", "kayak ekipmanı"]}, {"q": "Yazar ve kardeşi neden sıkıldı?", "o": ["Okuyacak kitapları kalmamıştı.", "Kulübeyi sevmediler.", "Anne babaları kızgındı.", "Radyo yoktu."]}, {"q": "Aile turnuvasını kim kazandı?", "o": ["yazarın babası", "yazar", "yazarın annesi", "kardeşi"]}, {"q": "Yazar tatil hakkında ne düşünüyor?", "o": ["En güzel tatillerinden biriydi.", "Tamamen mahvolmuştu.", "Dağlara gittiğine pişman.", "Gelecek sefer kışın gitmek istiyor."]}]}, "reunion7": {"p": ["Her yaz babamın ailesi, büyükanne ve büyükbabamın kırsaldaki evinde toplanır. Küçük bir etkinlik değil: bebeklerden doksan bir yaşındaki büyük halama kadar kırktan fazla akraba gelir.", "Sabah her zaman hareketlidir. Kadınlar mutfakta kocaman tencerelerde yemek pişirir, erkekler elma ağaçlarının altına masa ve sandalye koyar. Çocuklar koşuşturur ve küçük kuzenlerim genellikle en az bir kez dereye düşer. Benim işim herkesin fotoğrafını çekmek; kimse yerinde durmayınca bu kolay değil.", "Öğle yemeğinden sonra dedem eski bir fotoğraf albümü getirir. Annemle babamın çocukluk resimlerine bakarız ve herkes onların komik kıyafetlerine güler. Büyük halam, elektriğin olmadığı altmış yıl önceki köyü anlatır ve gençler dikkatle dinler.", "Akşam dedem kısa bir konuşma yapar ve kadehini kaldırır. \"Aileye,\" der, \"ve gelecek nesle.\" Masadaki bütün yüzlere bakar ve kendimi şanslı hissederim. Gelecekte nerede yaşarsam yaşayayım, her zaman geri döneceğim yerin burası olduğunu biliyorum."], "q": [{"q": "Buluşmaya genellikle kaç kişi gelir?", "o": ["yaklaşık on", "kırktan fazla", "yaklaşık yirmi", "yüze yakın"]}, {"q": "Yazarın sabahki görevi nedir?", "o": ["yemek pişirmek", "masaları düzenlemek", "çocuklara bakmak", "fotoğraf çekmek"]}, {"q": "Büyük hala ne anlatır?", "o": ["kendi çocuklarını", "uzun zaman önceki köy hayatını", "en sevdiği tarifleri", "havayı"]}, {"q": "Yazar sonunda nasıl hissediyor?", "o": ["yorgun ve sıkılmış", "ayrılmaktan üzgün", "gelecek için endişeli", "minnettar ve bu yere bağlı"]}]}, "school7": {"p": ["Pazartesi sabahı Zeynep yeni okulunun kapısından çok gergin bir şekilde geçti. Ailesi başka bir şehre taşınmıştı ve kimseyi tanımıyordu. Kalbi o kadar hızlı atıyordu ki zor nefes alıyordu.", "İdarede sekreter ona bir ders programı, binanın bir haritası ve bir dolabın anahtarını verdi. \"Sınıf öğretmenin Bay Kaya seninle 12 numaralı odada buluşacak,\" dedi gülümseyerek. Zeynep, odayı sonunda bulana kadar iki kez kayboldu.", "Bay Kaya onu sınıfa tanıttı ve Lale adında bir kızdan ona göz kulak olmasını istedi. Teneffüste Lale ona kantini gösterdi ve hangi öğretmenlerin sert olduğunu söyledi. Zeynep başta utangaçtı ama Lale de resim yapmayı çok sevdiğini söyleyince en sevdikleri sanatçılar hakkında konuşmaya başladılar.", "Cumaya gelindiğinde Zeynep yabancı gibi hissetmeyi bırakmıştı. Resim kulübüne katılmış, her şeyin nerede olduğunu öğrenmiş ve Lale'nin doğum günü partisine davet edilmişti. \"Pazartesi çok endişeliydim,\" dedi akşam yemeğinde annesine. \"Şimdi bu kadar çabuk olduğuna inanamıyorum.\""], "q": [{"q": "Zeynep pazartesi sabahı nasıl hissediyordu?", "o": ["çok gergin", "heyecanlı ve mutlu", "yorgun", "kızgın"]}, {"q": "Sekreter Zeynep'e ne verdi?", "o": ["üniforma ve bazı kitaplar", "öğretmen listesi", "ders programı, harita ve dolap anahtarı", "bir davetiye"]}, {"q": "Zeynep ve Lale'nin ortak noktası neydi?", "o": ["İkisi de resim yapmayı seviyordu.", "Aynı sokakta oturuyorlardı.", "Aynı öğretmenleri vardı.", "Aynı kulüpteydiler."]}, {"q": "Zeynep cumaya gelindiğinde nasıl hissetti?", "o": ["hâlâ kaybolmuş", "parti için endişeli", "okulda daha rahat", "geri dönmek istemiyor"]}]}, "wallet7": {"p": ["Kasımda soğuk bir akşam Kerem işten eve yürüyordu ki kaldırımda koyu renkli bir şey fark etti. Kahverengi, deri bir cüzdandı. Etrafına baktı ama sokak boştu.", "İçinde çok para, birkaç kart ve üzerinde bir isim yazan öğrenci kimliği vardı: Aylin Demir. Telefon numarası yoktu ama Kerem küçük bir köpekle birlikte genç bir kadının resmini buldu. Bir an düşündü. Para çok işine yarardı, çünkü yeni bir bisiklet için biriktiriyordu, ama onun olmadığını biliyordu.", "Ertesi sabah cüzdanı en yakın karakola götürdü. Memur bilgilerini yazdı ve ona teşekkür etti. \"Dürüst insanlar sandığınız kadar yaygın değil,\" dedi. Kerem omuz silkip işe gitti.", "İki gün sonra bir telefon aldı. Polis kendisine ulaşana kadar saatlerce ağlayan Aylin'di. Ona bir ödül vermek istedi ama Kerem reddetti. \"Bir dahaki sefere sadece daha dikkatli ol,\" dedi gülümseyerek. Bir hafta sonra kapısına küçük bir paket geldi: bir kutu çikolata ve \"Nazik olduğun için teşekkürler\" yazan bir kart."], "q": [{"q": "Kerem cüzdanın içinde ne buldu?", "o": ["yalnızca bir telefon numarası", "bir otobüs bileti", "bir anahtar", "para, kartlar ve öğrenci kimliği"]}, {"q": "Kerem parayı neden almadı?", "o": ["Polisten korkuyordu.", "Başkasına ait olduğunu biliyordu.", "Paraya ihtiyacı yoktu.", "Cüzdan boştu."]}, {"q": "Aylin ödül teklif edince Kerem ne dedi?", "o": ["Memnuniyetle kabul etti.", "Daha fazlasını istedi.", "Cevap vermedi.", "Reddetti."]}, {"q": "Aylin ona sonunda nasıl teşekkür etti?", "o": ["Onu yemeğe davet etti.", "Çikolata ve kart gönderdi.", "Ona biraz para verdi.", "Polisi tekrar aradı."]}]}, "bike7": {"p": ["Büyükbabam altmış sekiz yaşında bisiklete binmeyi öğrenmeye karar verdi. Bize söylediğinde şaka yaptığını sandık. Bütün hayatını insanların eşekle ya da yaya seyahat ettiği dağ köyünde geçirmişti ve hiç bisiklete oturmamıştı bile.", "Kardeşim ve ben ona evimizin yakınındaki boş otoparkta öğretmeyi teklif ettik. Büyükbabam çok küçük bir kask taktı ve biz selenin arkasını tuttuk. Başta o kadar çok sallandı ki üç metre sonra düştü. \"Göründüğünden zor,\" dedi gülerek.", "İki hafta boyunca her akşam çalıştık. Yavaş yavaş sırrın yere değil dümdüz ileri bakmak ve pedal çevirmeye devam etmek olduğunu öğrendi. On ikinci gün ona söylemeden selenin tutuşunu bıraktım. Fark etmeden önce yirmi metre yalnız sürdü!", "Bugün büyükbabam her cumartesi bisikletle pazara gidiyor. Komşularımız onu görünce el sallıyor, o da kocaman bir gülümsemeyle karşılık veriyor. \"Öğrenmek için asla yaşlı değilsin,\" diyor herkese. Onunla çok gurur duyuyoruz."], "q": [{"q": "Aile neden şaka yaptığını düşündü?", "o": ["Çok hastaydı.", "Zaten bir bisikleti vardı.", "Hiç bisiklete binmemişti.", "Şehirde yaşıyordu."]}, {"q": "Kaskla ilgili sorun neydi?", "o": ["Çok küçüktü.", "Çok ağırdı.", "Bozuktu.", "Ona ait değildi."]}, {"q": "On ikinci gün ne oldu?", "o": ["Yeniden düştü.", "Bisiklet satın aldı.", "Bilmeden tek başına sürdü.", "Bisikletle pazara gitti."]}, {"q": "Büyükbabanın insanlara mesajı nedir?", "o": ["İnsan her yaşta öğrenebilir.", "Bisiklet yalnızca gençler içindir.", "Eşekler bisikletten iyidir.", "Pazara yürüyerek gidilmelidir."]}]}, "bank7": {"p": ["Cem ilk işine başladığında müdürü, şirketin maaşını yatırabilmesi için bir banka hesabına ihtiyacı olduğunu söyledi. Daha önce hiç bir bankanın içine girmemişti; bu yüzden ablası Gül'e danıştı.", "Cumartesi sabahı istasyonun yakınındaki bir şubeye gittiler. Cem, Gül'ün söylediği gibi pasaportunu ve adres belgesini yanına aldı. Güler yüzlü bir görevli ona doldurması için bir form verdi ve farklı hesap türlerini anlattı. \"Öğrenci hesabında ücret yok,\" dedi, \"ama yalnızca yirmi beş yaşına kadar kullanabilirsin.\"", "Cem kartlı normal bir vadesiz hesap seçti. Görevli, bankamatiği her an kullanabileceğini ama PIN'ini asla kimseye söylememesi gerektiğini açıkladı. Ayrıca bakiyesini telefonda nasıl kontrol edeceğini gösterdi.", "Bir hafta içinde kartı postayla geldi ve ay sonunda ilk maaşı hesabındaydı. Cem kendini çok büyümüş hissetti. \"Şimdi tek yapmam gereken, hepsini ilk haftada harcamamayı öğrenmek,\" diye şaka yaptı."], "q": [{"q": "Cem neden banka hesabına ihtiyaç duydu?", "o": ["Tatil için biriktirmek için", "Şirketin maaşını yatırabilmesi için", "Öğrenci kartı almak için", "Ablası istediği için"]}, {"q": "Cem bankaya ne götürdü?", "o": ["eski banka kartını", "işverenini", "müdüründen bir mektup", "pasaportunu ve adres belgesini"]}, {"q": "Görevli PIN'i hakkında ne söyledi?", "o": ["Kartın üzerine yazmalı.", "Kimseye söylememeli.", "Her gün değiştirmeli.", "Ablasıyla paylaşmalı."]}, {"q": "Cem'in son şakası ne anlama geliyor?", "o": ["Bütün maaşını biriktirecek.", "İkinci bir hesap istiyor.", "Kartını kaybetti.", "Parasını çok çabuk harcayabilir."]}]}, "cook7": {"p": ["Geçen cumartesi altı arkadaşımı yemeğe davet ettim. Bu kadar çok kişiye ilk kez yemek yapıyordum ve her şeyin mükemmel olmasını istiyordum. Basit bir menü seçtim: domates çorbası, pilavlı tavuk ve elmalı kek.", "Saat ikide yemek yapmaya başladım. Çorba kolaydı ve kek harika kokuyordu. Sonra ilk hatamı yaptım: tavuk için zamanlayıcıyı kurmayı unuttum ve fırını açtığımda bir tarafı neredeyse simsiyahtı. Ağlayacak gibi oldum.", "Erken gelen arkadaşım Burcu günü kurtardı. Yanmış kısımları kesti ve tavuğu sarımsak ve limondan yapılmış lezzetli bir sosla kapladı. Konuklar geldiğinde hiçbir şeyin ters gittiğini kimse anlayamadı.", "Gece yarısına kadar yedik, güldük ve sohbet ettik. Herkes yemeğin en güzel kısmının kek olduğunu söyledi. O akşam iki şey öğrendim: her zaman zamanlayıcı kullan ve yardım istemekten asla çekinme."], "q": [{"q": "Yazarın hatası neydi?", "o": ["Tavuk için zamanlayıcı kurmayı unuttu.", "Çok fazla konuk davet etti.", "Zor bir menü seçti.", "Keki unuttu."]}, {"q": "Burcu nasıl yardım etti?", "o": ["Yeni bir tavuk pişirdi.", "Konuklara servis yaptı.", "Yanık kısımları sosla gizledi.", "Bulaşıkları yıkadı."]}, {"q": "Yemeğin hangi kısmı en çok beğenildi?", "o": ["kek", "çorba", "tavuk", "pilav"]}, {"q": "Yazar ne öğrendi?", "o": ["konuklara asla yemek yapmamayı", "hazır yemek almayı", "zamanlayıcı kullanmayı ve yardım kabul etmeyi", "daha erken pişirmeye başlamayı"]}]}, "volun7": {"p": ["Her iki haftada bir cumartesi, kasabamızın kenarındaki bir hayvan barınağında gönüllü olarak çalışıyorum. Barınak, çoğu sokakta sahipsiz bulunmuş yaklaşık altmış köpek ve kediye bakıyor.", "Günüm dokuzda başlar. Önce hayvanları beslemeye ve kafeslerini temizlemeye yardım ederim. Sonra köpekleri barınağın arkasındaki tarlada gezdiririm. Her zaman çok heyecanlıdırlar ve bazıları o kadar sert çeker ki neredeyse düşüyorum!", "Öğleden sonra kedilerle otururum. Birçoğu kötü muamele gördüğü için çekingendir. Onlarla sessizce konuşur ve bana gelmelerini beklerim. Haftalar sürebilir ama bir kedinin sonunda kucağınıza çıkması harika bir şeydir.", "En güzel gün, bir hayvanın sahiplenildiği gündür. Geçen hafta bir aile Pepper adında küçük kahverengi bir köpeği eve götürdü. Giderlerken barınaktaki herkes alkışladı. Onun adına sevindim ama gözlerimin dolduğunu itiraf etmeliyim."], "q": [{"q": "Hayvanların çoğu nereden geliyor?", "o": ["Barınakta doğmuşlar.", "Dükkânlardan alınmışlar.", "Çiftliklerden gelmişler.", "Sokakta bulunmuşlar."]}, {"q": "Yazar sabah ne yapıyor?", "o": ["Kedileri eğitiyor.", "Hayvanları besliyor ve kafesleri temizliyor.", "Telefonlara bakıyor.", "Fotoğraf çekiyor."]}, {"q": "Kedilerin çoğu neden çekingen?", "o": ["Çok yaşlılar.", "Hastalar.", "İnsanlardan hiç hoşlanmıyorlar.", "Kötü muamele görmüşler."]}, {"q": "Pepper giderken yazar nasıl hissetti?", "o": ["kızgın", "mutlu ama duygulanmış", "sıkılmış", "endişeli"]}]}, "mobile7": {"p": ["Eski telefonum geçen hafta sonunda bozuldu. Ekranı aylardır çatlaktı ve pili yalnızca iki saat dayanıyordu. Yeni bir telefona ihtiyacım olduğunu biliyordum ama çok farklı model olduğu için hangisini seçeceğime dair hiçbir fikrim yoktu.", "Önce arkadaşlarıma sordum. Herkes farklı bir şey önerdi ve her biri kendi telefonunun en iyisi olduğunu söyledi. Sonra çevrim içi bazı yorumlar okudum ve gerçekten ihtiyacım olan özelliklerin bir listesini yaptım: iyi bir kamera, uzun süre dayanan pil ve makul bir fiyat.", "Fiyatları karşılaştırmak için üç dükkâna gittim. İlkinde bir satıcı beni, ihtiyacım olmayan en pahalı modeli almaya ikna etmeye çalıştı. İkincisinde çalışanlar daha yardımcıydı ve taahhütlü hat ile peşin ödeme arasındaki farkı açıkladılar. Üçüncüsünde tam istediğimi indirimde buldum.", "Ödedim, yeni telefonumu eve götürdüm ve akşamı fotoğraflarımı kopyalayarak geçirdim. Mükemmel çalışıyor ve acele etmediğime sevindim. Tavsiyem: alışverişe gitmeden önce neye ihtiyacın olduğuna karar ver ve kimsenin sana bundan fazlasını satmasına izin verme."], "q": [{"q": "Yazar neden yeni telefona ihtiyaç duydu?", "o": ["Otobüste kaybetti.", "Arkadaşlarının hepsinde yenisi vardı.", "Eskisi bozuktu ve pili kötüydü.", "Çalındı."]}, {"q": "Alışverişe gitmeden önce ne yaptı?", "o": ["İhtiyaç duyduğu özelliklerin listesini yaptı.", "Ailesinden para istedi.", "Eski telefonunu sattı.", "Koruyucu kılıf aldı."]}, {"q": "İlk dükkânda sorun neydi?", "o": ["Fiyatlar gösterilmemişti.", "Dükkân kapalıydı.", "Satıcı pahalı bir modeli zorla satmaya çalıştı.", "Çalışanlar onunla konuşmadı."]}, {"q": "Yazarın tavsiyesi nedir?", "o": ["Alışverişten önce neye ihtiyacın olduğuna karar ver.", "Her zaman en ucuz telefonu al.", "Arkadaşlarının senin yerine seçmesini iste.", "Asla dükkândan alma."]}]}};window.READINGS=(window.READINGS||[]).concat(A);window.READINGS_TR=Object.assign(window.READINGS_TR||{},T)})();
